    [42] = {
      beijing = 1351,
      dialog = 3,
      music = "1024_2024SummerSP",
      renwu = "npc",
      sentence = "As I did my best to restrain a smile, all of a sudden, ice-cold seawater splashed up over my ankles, causing me to shiver.",
